#!/usr/bin/env python3
"""Generates src/codepages.rs: 256-entry byte -> UTF-16 tables for the single-byte
Windows/OEM code pages SQL Server uses for CHAR/VARCHAR/TEXT data.

Source of truth: Python's `codecs` (cp437, cp850, cp874, cp1250..cp1258). Bytes the codec
does not define become U+FFFD, which is what go-mssqldb's internal/cp tables contain
for them ("UNDEFINED").

If the go-mssqldb module is present in the Go module cache, every table is compared
with go-mssqldb's internal/cp/cpNNNN.go and any difference is reported. go-mssqldb's
value wins on a mismatch, because dl-tds must decode byte-for-byte like the Go agent
it replaces.

Usage: python testdata/gen_codepages.py   (run from crates/dl-tds)
"""

import os
import re
import sys

PAGES = [437, 850, 874, 1250, 1251, 1252, 1253, 1254, 1255, 1256, 1257, 1258]
GO_DIR = os.path.join(
    os.path.expanduser("~"),
    "go", "pkg", "mod", "github.com", "microsoft", "go-mssqldb@v1.10.0", "internal", "cp",
)


def python_table(cp):
    out = []
    for b in range(256):
        try:
            s = bytes([b]).decode("cp%d" % cp)
        except UnicodeDecodeError:
            s = "\ufffd"
        assert len(s) == 1, (cp, b, s)
        out.append(ord(s))
    return out


def go_table(cp):
    path = os.path.join(GO_DIR, "cp%d.go" % cp)
    if not os.path.exists(path):
        return None
    text = open(path, encoding="utf-8").read()
    m = re.search(r"sb:\s*\[256\]rune\{(.*?)\n\s*\},", text, re.S)
    if not m:
        return None
    vals = re.findall(r"^\s*(-?0x[0-9A-Fa-f]+|-?\d+)\s*,", m.group(1), re.M)
    vals = [int(v, 0) for v in vals]
    return vals if len(vals) == 256 else None


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    target = os.path.join(here, "..", "src", "codepages.rs")
    lines = [
        "//! Byte -> UTF-16 tables for single-byte code pages.",
        "//!",
        "//! GENERATED by `testdata/gen_codepages.py` from Python's `codecs`, checked against",
        "//! go-mssqldb v1.10.0 `internal/cp`. Do not edit by hand. Undefined bytes map to U+FFFD.",
        "",
    ]
    diffs = 0
    for cp in PAGES:
        table = python_table(cp)
        go = go_table(cp)
        if go is None:
            print("cp%d: go-mssqldb table not found, using Python only" % cp)
        else:
            for b in range(256):
                if go[b] != table[b]:
                    diffs += 1
                    print("cp%d byte 0x%02X: python U+%04X, go-mssqldb U+%04X -> using go" % (cp, b, table[b], go[b]))
                    table[b] = go[b]
        lines.append("/// Code page %d." % cp)
        lines.append("pub(crate) static CP%d: [u16; 256] = [" % cp)
        for row in range(0, 256, 8):
            lines.append("    " + " ".join("0x%04X," % v for v in table[row:row + 8]))
        lines.append("];")
        lines.append("")
    open(target, "w", encoding="utf-8", newline="\n").write("\n".join(lines))
    print("wrote %s (%d differences from Python resolved in favour of go-mssqldb)" % (target, diffs))
    return 0


if __name__ == "__main__":
    sys.exit(main())
